const msg = $input.first().json;
const text = msg?.message?.text || '';
const chatId = msg?.message?.chat?.id;
const firstName = msg?.message?.from?.first_name || '';
return [{ json: { text, chatId, firstName } }];

const CLIENT_ID = $env.EBAY_CLIENT_ID;
const CLIENT_SECRET = $env.EBAY_CLIENT_SECRET;
const REFRESH_TOKEN = $env.EBAY_REFRESH_TOKEN;

const chatId = $input.first().json.chatId;
const userText = $input.first().json.text;
const firstName = $input.first().json.firstName;

try {
  const credentials = Buffer.from(CLIENT_ID + ':' + CLIENT_SECRET).toString('base64');

  // Get token with all needed scopes
  const tokenResp = await this.helpers.request({
    method: 'POST',
    url: 'https://api.ebay.com/identity/v1/oauth2/token',
    headers: {
      'Authorization': 'Basic ' + credentials,
      'Content-Type': 'application/x-www-form-urlencoded'
    },
    form: {
      grant_type: 'refresh_token',
      refresh_token: REFRESH_TOKEN,
      scope: 'https://api.ebay.com/oauth/api_scope/sell.fulfillment.readonly https://api.ebay.com/oauth/api_scope/sell.inventory.readonly https://api.ebay.com/oauth/api_scope/sell.marketing.readonly'
    }
  });

  const { access_token } = JSON.parse(tokenResp);

  // Fetch last 90 days orders (covers most questions)
  const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString();
  const ordersResp = await this.helpers.request({
    method: 'GET',
    url: `https://api.ebay.com/sell/fulfillment/v1/order?filter=creationdate:[${ninetyDaysAgo}..]&limit=200`,
    headers: { 'Authorization': `Bearer ${access_token}` }
  });

  const { orders = [], total = 0 } = JSON.parse(ordersResp);

  // Build structured data for Claude
  const orderData = orders.map(o => ({
    orderId: (o.orderId || '').slice(-10),
    date: o.creationDate ? new Date(o.creationDate).toISOString().split('T')[0] : null,
    amount: parseFloat(o.pricingSummary?.total?.value || 0),
    currency: o.pricingSummary?.total?.currency || 'USD',
    buyer: o.buyer?.username || 'unknown',
    status: o.orderFulfillmentStatus || 'unknown',
    items: (o.lineItems || []).map(li => ({
      title: li.title || 'N/A',
      quantity: li.quantity || 1,
      price: parseFloat(li.lineItemCost?.value || 0)
    }))
  }));

  // Fetch active listings count
  let listingsSummary = { total: 0, published: 0 };
  try {
    const listResp = await this.helpers.request({
      method: 'GET',
      url: 'https://api.ebay.com/sell/inventory/v1/offer?limit=100',
      headers: { 'Authorization': `Bearer ${access_token}` }
    });
    const { offers = [], total: lt = 0 } = JSON.parse(listResp);
    listingsSummary = {
      total: lt,
      published: offers.filter(o => o.status === 'PUBLISHED').length,
      unpublished: offers.filter(o => o.status !== 'PUBLISHED').length
    };
  } catch(e) { /* ignore listings errors */ }

  return [{ json: { chatId, userText, firstName, orderData, totalOrders: total, listingsSummary, today: new Date().toISOString().split('T')[0] } }];

} catch(e) {
  return [{ json: { chatId, userText, firstName, error: e.message, orderData: [], totalOrders: 0, listingsSummary: { total: 0, published: 0 }, today: new Date().toISOString().split('T')[0] } }];
}

const CLAUDE_API_KEY = $env.CLAUDE_API_KEY || $env.ANTHROPIC_API_KEY || '';

const { chatId, userText, firstName, orderData, totalOrders, listingsSummary, today, error } = $input.first().json;

if (error) {
  return [{ json: { chatId, reply: `❌ eBay-ից տվյալ ստանալու սխալ:\n${error}\n\nՍտուգիր Client Secret-ը կամ Refresh Token-ը։` } }];
}

if (!CLAUDE_API_KEY) {
  return [{ json: { chatId, reply: '❌ CLAUDE_API_KEY կամ ANTHROPIC_API_KEY env variable-ը սահմանված չէ։' } }];
}

const systemPrompt = `Դու eBay seller-ի AI assistant ես։ Քո անունն է Prime Outlet Bot։
Օգտվողի անունը ${firstName || 'seller'} է։
ՀԱՅԵՐԵՆ պատասխանիր, կարճ ու հստակ, HTML formatting-ով (Telegram-ի համար)։
Օգտագործիր <b>bold</b> կարևոր թվերի համար։
Եթե թվեր ես հաշվում, ցույց տուր աշխատանքը (քանի order, ընդհանուր գումար)։

Հargest DATE: ${today}

eBay ORDERS DATA (last 90 days, ${orderData.length} orders loaded from total ${totalOrders}):
${JSON.stringify(orderData, null, 2)}

LISTINGS SUMMARY:
- Total offers: ${listingsSummary.total}
- Published: ${listingsSummary.published}
- Unpublished: ${listingsSummary.unpublished || 0}

Instructions:
- Օգտատերը կարող է հարցնել ամեն ինչ՝ "վերջի 10 օրում վաճառք", "ամենաշատ վաճառված ապրանք", "երեքշաբթի ինչ եղավ" etc.
- Ճշտորեն հաշվիր ըստ date-ների
- Եթե data-ն բավական չէ (90 օրից հին), ասա
- Revenue հաշվելիս գումարիր amount field-ները`;

try {
  const response = await this.helpers.request({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': CLAUDE_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 1024,
      system: systemPrompt,
      messages: [{ role: 'user', content: userText }]
    })
  });

  const result = JSON.parse(response);
  const reply = result.content?.[0]?.text || 'Պատասխան ստանալ չհաջողվեց։';
  return [{ json: { chatId, reply } }];

} catch(e) {
  return [{ json: { chatId, reply: `❌ Claude API սխալ: ${e.message}` } }];
}
